const clickupUrl = $('Create ClickUp Task').first().json.url|| 'Task created successfully';
const taskTitle = $('Build Task Payload').first().json.ai_result?.title || $('Build Task Payload').first().json.clickup_task_name || '';

return [{
  json: {
    reply_message: `Thanks — I've logged this and sent it to the dev team.\n\n📝 Task: ${taskTitle}\n🔗 Track: ${clickupUrl}`,
    final_status: 'task_created',
    clickup_url: clickupUrl,
    from: $('Build Task Payload').first().json.from,
    phone_number_id: $('Build Task Payload').first().json.phone_number_id,
    recipientPhoneNumber: $('WhatsApp Trigger').first().json.messages[0].from
  }
}];

const ai = $input.first().json.ai_result;

const priorityMap = { 'Urgent': 1, 'High': 2, 'Medium': 3, 'Low': 4 };
const priority = priorityMap[ai.priority] || 3;

const tags = [
  'whatsapp',
  ai.request_type,
  ai.module,
  ai.urgency
].filter(t => typeof t === 'string' && t.trim().length > 0);

const description = [
  `Type: ${ai.request_type     || 'N/A'}`,
  `Module: ${ai.module         || 'N/A'}`,
  `Priority: ${ai.priority     || 'N/A'}`,
  `Urgency: ${ai.urgency       || 'N/A'}`,
  `Size: ${ai.estimated_category || 'N/A'}`,
  '',
  '── Description ──',
  ai.description || '',
  '',
  '── Summary for team ──',
  ai.summary_for_team || '',
  '',
  '── Source ──',
  `Client: ${ai.client_name   || 'Unknown'}`,
  `Project: ${ai.project_name || 'Unknown'}`,
  'Via: WhatsApp'
].join('\n');

const body = {
  name:        ai.title,
  description: description,
  assignees:   Array.isArray($input.first().json.clickup_assignees)
                 ? $input.first().json.clickup_assignees
                 : [],
  priority:    priority,
  tags:        tags,
  status:      'Open',
  notify_all:  true
};

return [{
  json: {
    ...$input.first().json,
    clickup_list_id: ai.clickup_list_id,
    clickup_body:    body
  }
}];

return [{
  json: {
    reply_message: $('Parse Json').first().json.ai_result.clarification_question,
    final_status: 'awaiting_client_clarification',
    from: $('WhatsApp Trigger').first().json.messages[0].from,
    phone_number_id: $('WhatsApp Trigger').first().json.metadata.phone_number_id,
    recipientPhoneNumber: $('WhatsApp Trigger').first().json.messages[0].from
  }
}];

return [{
  json: {
    reply_message: "Got it 👍 Is this about the same issue as before, or is this a new request?",
    final_status: 'awaiting_update_or_new_issue',
    from: $('WhatsApp Trigger').first().json.messages[0].from,
    phone_number_id: $('Normalize Incoming Message').first().json.phone_number_id,
    recipientPhoneNumber: $('WhatsApp Trigger').first().json.messages[0].from
  }
}];

const row = $input.first().json;

let parsed = {};

try {
  let raw = row.output || row.text || row.response || '';

  if (typeof raw === 'object') {
    parsed = raw;
  } else {
    raw = String(raw)
      .replace(/```json/gi, '')
      .replace(/```/g, '')
      .trim();

    const start = raw.indexOf('{');
    const end = raw.lastIndexOf('}');

    if (start !== -1 && end !== -1) {
      parsed = JSON.parse(raw.slice(start, end + 1));
    }
  }
} catch (e) {
  parsed = {
    project_name: 'Unknown',
    clickup_list_id: '',
    clickup_task_id: '',
    title: 'Parse Error',
    description: 'AI output invalid JSON'
  };
}

return [
  {
    json: {
      ...row,
      ai_result: parsed
    }
  }
];

const trigger = $('WhatsApp Trigger').first().json;
const inbound = trigger.messages?.[0] || {};
const msg = $json.message?.text || '';

let attachment = null;
if (inbound.type === 'document' && inbound.document) {
  attachment = {
    type: 'document',
    id: inbound.document.id || '',
    filename: inbound.document.filename || 'Attachment',
    mime_type: inbound.document.mime_type || '',
    caption: inbound.document.caption || ''
  };
} else if (inbound.type === 'image' && inbound.image) {
  const ext = (inbound.image.mime_type || '').split('/')[1] || 'jpg';
  attachment = {
    type: 'image',
    id: inbound.image.id || '',
    filename: `image_${inbound.image.id || Date.now()}.${ext}`,
    mime_type: inbound.image.mime_type || '',
    caption: inbound.image.caption || ''
  };
}

return [{
  json: {
    from: trigger.contacts?.[0]?.wa_id ? `whatsapp:+${trigger.contacts[0].wa_id}` : '',
    phone_raw: inbound.from || '',
    client_message: msg,
    client_name: trigger.contacts?.[0]?.profile?.name || 'Unknown Client',
    timestamp: new Date().toISOString(),
    phone_number_id: trigger.metadata?.phone_number_id || '',
    attachment,
    raw_payload: trigger
  },
  binary: $input.item.binary
}];

