// Pulls clickup_task_id correctly from conversation record via AI result
const aiResult = $input.first().json.ai_result;
const projectName = aiResult.project_name || '';
const clientName  = aiResult.client_name  || '';
const newInfo     = aiResult.description  || $input.first().json.client_message || '';
const summaryForTeam = aiResult.summary_for_team || '';

// FIXED: read clickup_task_id, never clickup_list_id
const taskId =  $input.first().json.ai_result.clickup_task_id|| '';
const clickupUrl = `https://app.clickup.com/t/${$input.first().json.ai_result.clickup_task_id}`;

const attachmentFilename = $input.first().json.attachment?.filename || '';
const attachmentText = attachmentFilename ? `\n\nAttachment: ${attachmentFilename}` : '';

const devSlackMentions = (Array.isArray(aiResult.assigned_developers)
  ? aiResult.assigned_developers
  : []
).map(d => `<@${String(d.slack_id || d).replace(/^@/, '')}>`).join(' ');

// FIXED: description is a plain string — no nested object
const updatedDescription = [
  '[UPDATED by client]',
  '',
  `New information from ${clientName}:`,
  newInfo,
  attachmentText,
  '',
  '── Summary ──',
  summaryForTeam
].join('\n');

const slackUpdateMessage = [
  '🔄 *Task Updated by Client*',
  '',
  `🏢 *Project:* ${projectName}`,
  `👤 *Client:* ${clientName}`,
  '',
  '💬 *New info:*',
  newInfo,
  attachmentText,
  '',
  `🔗 *Task:* ${clickupUrl}`,
  '',
  `👨‍💻 *Devs:* ${devSlackMentions || 'Not Assigned'}`
].join('\n');

return [{
  json: {
    // carry forward everything needed downstream
    client_name:          clientName,
    project_name:         projectName,
    summary_for_team:     summaryForTeam,
    client_message:       newInfo,
    clickup_task_id:      taskId,
    clickup_url:          clickupUrl,
    phone_number_id:      $input.first().json.phone_number_id,
    attachment:           $input.first().json.attachment || null,
    // FIXED: flat string, not a nested object
    clickup_description:  updatedDescription,
    slack_update_message: slackUpdateMessage
  },
  binary: $input.item.binary
}];

const payload = $('Build Update Task Payload').first().json;
const clickupUrl = payload.clickup_url || 'your task';

return [{
  json: {
    reply_message: `Got it! I've added your update to the existing task and notified the dev team. 🔄\n\n🔗 Track here: ${clickupUrl}`,
    final_status: 'task_updated',
    from: $('WhatsApp Trigger').first().json.messages[0].from,
    phone_number_id: payload.phone_number_id || $('WhatsApp Trigger').first().json.metadata.phone_number_id,
    recipientPhoneNumber: $('WhatsApp Trigger').first().json.messages[0].from
  }
}];
